using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using System.Windows;using System.Windows.Media;using System.Windows.Threading;using RingTimer;
class DurationPerformance {
 static void Pump(int ms){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(ms)};timer.Tick+=(s,e)=>{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}
 [STAThread]static int Main(string[] args){Native.SetProcessDPIAware();var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};MenuWindow menu=null;try{
 Theme.Apply(true,null,null,null);var timer=new TimerFeature(new TimerEngine(new TimerState(),()=>DateTime.UtcNow),()=>{});menu=new MenuWindow(new FeatureRegistry(timer,new StatsFeature(new StatsStore(null))),()=>{},()=>{}){Left=60,Top=30,AnimationsEnabled=false};menu.OpenFeature("timer");menu.Reveal();Pump(500);menu.AnimationsEnabled=true;
 var intervals=new List<double>();var startup=new List<double>();var process=Process.GetCurrentProcess();var cpu=process.TotalProcessorTime;var total=Stopwatch.StartNew();
 for(int run=0;run<12;run++){var clock=Stopwatch.StartNew();double last=-1;TimeSpan lastRender=TimeSpan.MinValue;EventHandler render=(s,e)=>{var stamp=((RenderingEventArgs)e).RenderingTime;if(stamp==lastRender)return;lastRender=stamp;double ms=clock.Elapsed.TotalMilliseconds;if(ms<=190&&run>1){if(last>=0)intervals.Add(ms-last);last=ms;}};
 CompositionTarget.Rendering+=render;timer.Panel.OpenEditor(run%2==0?"work":"rest");startup.Add(clock.Elapsed.TotalMilliseconds);Pump(500);CompositionTarget.Rendering-=render;timer.Panel.CancelEditor();Pump(330);}
 intervals.Sort();startup.Sort();process.Refresh();string report="label="+args[1]+" tier="+(RenderCapability.Tier>>16)+" dpi="+Native.ScaleFor(menu.Handle)+" opening_samples="+intervals.Count+" median_ms="+intervals[intervals.Count/2].ToString("F2")+" p95_ms="+intervals[(int)((intervals.Count-1)*.95)].ToString("F2")+" setup_median_ms="+startup[startup.Count/2].ToString("F2")+" cpu_one_core_percent="+((process.TotalProcessorTime-cpu).TotalSeconds/total.Elapsed.TotalSeconds*100).ToString("F1")+" private_mb="+(process.PrivateMemorySize64/1048576.0).ToString("F1");Directory.CreateDirectory(args[0]);File.WriteAllText(Path.Combine(args[0],args[1]+".txt"),report);Console.WriteLine(report);return 0;
 }catch(Exception e){Console.WriteLine(e);return 1;}finally{if(menu!=null){menu.Disposing=true;menu.Close();}app.Shutdown();}}
}
